CREATE TABLE "alimentos" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "alimentos_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"clave" text NOT NULL,
	"nombre" text NOT NULL,
	"estado" text DEFAULT 'pendiente' NOT NULL,
	"fuente" text,
	"confianza" double precision DEFAULT 0 NOT NULL,
	"gramos" double precision,
	"gramos_unidad" double precision,
	"ingredientes" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"componentes" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"intentos" smallint DEFAULT 0 NOT NULL,
	"proximo_intento" timestamp with time zone DEFAULT now() NOT NULL,
	"error" text,
	"creado" timestamp with time zone DEFAULT now() NOT NULL,
	"actualizado" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "alimentos_clave_unique" UNIQUE("clave")
);
